function decodeI16(b64) {
  const s = atob(b64), n = s.length >> 1, a = new Int16Array(n);
  for (let i = 0; i < n; i++) a[i] = s.charCodeAt(2 * i) | (s.charCodeAt(2 * i + 1) << 8);
  return a;
}
function circuitPoints(id) {
  const a = decodeI16(CIRCUIT_DATA[id].pts), pts = [];
  for (let i = 0; i < a.length; i += 3) pts.push(new THREE.Vector3(a[i] / 10, a[i + 2] / 20, a[i + 1] / 10));
  return pts;
}

