    if (bd > 1600) best = this.grid.nearestGlobal(car.x, car.z);
    car.ti = best;
    let i0 = best;
    let along = (car.x - px[i0]) * this.tx[i0] + (car.z - pz[i0]) * this.tz[i0];
    if (along < 0) { i0 = (best - 1 + N) % N; along = (car.x - px[i0]) * this.tx[i0] + (car.z - pz[i0]) * this.tz[i0]; }
    const i1 = (i0 + 1) % N, t = clamp(along / this.ds, 0, 1);
