    car.bank = lerp(this.bank[i0], this.bank[i1], t);
    car.roadY = lerp(this.py[i0], this.py[i1], t) + car.lat * car.bank;
    car.tnx = nx; car.tnz = nz; car.ttx = nz; car.ttz = -nx;
