    this.buildArmco(); this.buildTyreWalls(1 / 50);
    const gm = this.grassMaterial('#e6cc84', '#8a7036');
    this.plantChunks({ types: [[G.tuft, 1, 0.9, 1.9, gm]], density: 0.5 * q.grass, band: [0.1, 16], colors: this.mixColor('#e0c67e', '#b8994e'), yJit: 0.05, trunks: false });
